# -*- coding: utf-8 -*-
"""The deeper sections of the Greece wave-1 pages (Ben 22.10.2026: "deepen and deepen ... prove we are above any other page").
Imported by build_pages.py after its helpers exist: make(ns) returns the extra blocks and FAQ entries per page. Facts only from
facts.json (sources in facts.md); worked examples are computed from the same rates as the tools."""


def make(ns):
    K, F, R, n, pct, buy, ILS, B, yoy, gtax = (ns[k] for k in ("K", "F", "R", "n", "pct", "buy", "ILS", "B", "yoy", "gtax"))
    fx = ns["fx"]
    OFFICIAL = [("בנק יוון, מדד מחירי הדירות", "https://www.bankofgreece.gr/en/news-and-media/press-office/news-list/news?announcement=ac5ae869-3e94-4550-b486-ef00c4292e07"),
                ("משרד האוצר היווני, תקציב 2027", "https://minfin.gov.gr/wp-content/uploads/2026/10/Greece_DBP_2027_final.pdf"),
                ("פורטל הדיור, הקפאת ההשכרה הקצרה", "https://stegasi.gov.gr/programs/prosorinoi-periorismoi-stis-vrachychronies-misthoseis/"),
                ("משרד ההגירה, גולדן ויזה", "https://migration.gov.gr/en/golden-visa/"),
                ("רשות המסים בישראל, מדריך 2025", "https://www.gov.il/BlobFolder/generalpage/income-tax-guide-knowyourright/he/Guides_IncomeTax_da-2025.pdf")]
    TREATY = ("האמנה, אוסף האמנות של האו״ם, כרך 2274", "https://treaties.un.org/doc/Publication/UNTS/Volume%202274/v2274.pdf")
    TL = K.timeline("מה השתנה ומה עומד להשתנות", [("1.1.2026", "מדרגת מס שכירות חדשה של 25%", "law"), ("1.11.2026", "סוף ההערות לציבור על 15.45%", "plan"),
                                                ("31.12.2026", "סוף ההקפאה של Airbnb והשעיית המע״מ", "end"), ("1.7.2027", "15.45% לזרים, אם יעבור", "plan")])
    LADDER = K.bars("מחיר מבוקש למ״ר, רבעון 2 של 2026", [(R[k]["he"].split(" (")[0], R[k]["m2"], "€" + n(R[k]["m2"])) for k in ("vouliagmeni", "athens-south", "athens-north", "thessaloniki", "piraeus", "athens-center", "athens-west")],
                    note="Spitogatos, מחירים מבוקשים. סלוניקי לשם השוואה.", hi=5)

    # worked examples (the same rates as grbuy)
    def case(p, agent, mort_ltv=0, vat=False):
        c = buy(p, agent=agent)
        if vat: c["tt"] = 0; c["vat"] = p * B["vat"]; c["costs"] = sum(v for k, v in c.items() if k in ("tt", "notary", "cad", "lawyer", "agent", "vat"))
        loan = p * mort_ltv / 100; mc = loan * B["cad_mortgage"] + B["cad_fixed"] + 750 if loan else 0
        return c["costs"] + mc, p - loan + c["costs"] + mc, loan
    ex1 = case(150000, 2); ex2 = case(250000, 2, 60); ex3 = case(400000, 0)
    EXAMPLES = K.table("שלוש עסקאות לדוגמה, עם כל העלויות", ["העסקה", "עלויות הקנייה", "כמה להביא", "בשקלים"], [
        ["דירה יד שנייה במרכז אתונה, <bdi>€150,000</bdi>, עם מתווך", "<bdi>€%s</bdi>" % n(ex1[0]), "<bdi>€%s</bdi>" % n(ex1[1]), "<bdi>%s</bdi>" % ILS(ex1[1])],
        ["דירה בפיראוס, <bdi>€250,000</bdi>, משכנתא יוונית 60%", "<bdi>€%s</bdi>" % n(ex2[0]), "<bdi>€%s</bdi>" % n(ex2[1]), "<bdi>%s</bdi>" % ILS(ex2[1])],
        ["דירה חדשה בפרברי הדרום, <bdi>€400,000</bdi>, מע״מ מושעה, בלי מתווך", "<bdi>€%s</bdi>" % n(ex3[0]), "<bdi>€%s</bdi>" % n(ex3[1]), "<bdi>%s</bdi>" % ILS(ex3[1])]])
    cmp_rows = [["מרכז אתונה", "<bdi>€2,500</bdi>", "<bdi>+%s</bdi>" % pct(R["athens-center"]["yoy"]), "<bdi>€800,000</bdi>", "מוקפא במחוזות 1 עד 3", "כשעתיים ורבע"],
                ["סלוניקי", "<bdi>€2,714</bdi>", "<bdi>+%s</bdi>" % pct(R["thessaloniki"]["yoy"]), "<bdi>€800,000</bdi>", "מוקפא במרכז העיר מ־1.7.2026", "לא נבדק"],
                ["חאניה, כרתים", "<bdi>€3,102</bdi>", "<bdi>+%s</bdi>" % pct(R["chania"]["yoy"]), "<bdi>€800,000</bdi>", "פתוח", "כשעתיים להרקליון"],
                ["חלקידיקי", "<bdi>€2,759</bdi>", "<bdi>+%s</bdi>" % pct(R["halkidiki"]["yoy"]), "<bdi>€400,000</bdi>", "פתוח", "דרך סלוניקי"]]
    COMPARE = K.table("אתונה, סלוניקי, כרתים או חלקידיקי", ["אזור", "מחיר למ״ר", "שינוי בשנה", "סף גולדן ויזה", "רישום Airbnb חדש", "טיסה מתל אביב"], cmp_rows)

    ath = [
        '<h2>סולם המחירים של אתונה</h2>',
        '<p>ההבדל בין האזורים של אתונה רבתי גדול יותר מההבדל בין אתונה לשאר יוון. בווליאגמני, על הריביירה, המחיר המבוקש גבוה פי שלושה מבפרברי המערב. '
        'מרכז העיר, שבו רוב הקונים הישראלים מחפשים, נמצא בתחתית הסולם, ביחד עם פיראוס.</p>', LADDER,
        '<h2>אתונה, סלוניקי, כרתים או חלקידיקי</h2>',
        '<p>רוב הקונים הישראלים מתלבטים בין ארבעה יעדים. ההבדל ביניהם הוא לא רק במחיר: הסף של הגולדן ויזה, ההקפאה של Airbnb והגישה מישראל משנים את החשבון. '
        'כרתים נחשבת אי גדול, ולכן גם בה הסף לגולדן ויזה הוא <bdi>€800,000</bdi>.</p>', COMPARE,
        '<h2>שלוש עסקאות לדוגמה</h2>',
        '<p>אותם שיעורים שבמחשבון, על שלוש עסקאות אופייניות. בעסקה עם משכנתא, "כמה להביא" הוא ההון העצמי ועוד כל העלויות, כולל רישום המשכנתא ובדיקת הבנק.</p>', EXAMPLES,
        '<h2>השכרה לטווח ארוך: פטור ממס ל־36 חודשים</h2>',
        '<p>כדי להחזיר דירות לשוק השכירות הרגיל, יוון פוטרת ממס הכנסה, ל־36 חודשים, שכירות של דירה עד 120 מ״ר שהושכרה לפחות לשלוש שנים, אם עמדה ריקה שלוש שנים לפני כן, '
        'או אם בשנה הקודמת הושכרה רק לטווח קצר. הפטור חל על חוזים שנחתמים עד 31.12.2026, והצעת התקציב מאריכה אותו עד סוף 2027. במרכז אתונה, שבו אי אפשר לרשום Airbnb חדש, '
        'זה מסלול שכדאי לבדוק עם רואה חשבון יווני לפני שמחשבים תשואה.</p>',
        '<h2>מה משתנה בחוק, ומתי</h2>', TL,
        K.sources(OFFICIAL[:4]),
    ]

    Q = F["prices"]["bog_index"]["quarterly_series_2016_2026"]
    yr_rows = [[y, "<bdi>%s</bdi>" % n(Q["greater_athens_all"][y + "-Q2"], 1), "<bdi>%s</bdi>" % n(Q["whole_country_all"][y + "-Q2"], 1), "<bdi>%s</bdi>" % n(Q["thessaloniki_all"][y + "-Q2"], 1)] for y in [str(x) for x in range(2016, 2027)]]
    HOODS = K.table("שכונות ואזורים באתונה: מה שפורסם", ["שכונה או אזור", "איפה", "מחיר או תשואה שפורסמו", "Airbnb חדש"], [
        ["קוקאקי", "מחוז 1, מתחת לאקרופוליס", "לא פורסם מחיר לשכונה", "מוקפא"],
        ["קולונקי", "מחוז 1, מרכז העיר", "תשואה ברוטו <bdi>3.39%</bdi> לדירת שני חדרי שינה", "מוקפא"],
        ["אקסרכיה ונאפולי", "מחוז 1", "לא פורסם", "מוקפא"],
        ["פנגרטי", "מחוז 2", "תשואה ברוטו <bdi>3.92%</bdi> לדירת שני חדרי שינה", "מוקפא"],
        ["ניאוס קוסמוס ומטס", "מחוז 2", "לא פורסם", "מוקפא"],
        ["פטרלונה, תיסיו וגאזי", "מחוז 3", "לא פורסם", "מוקפא"],
        ["פטיסיון ואחרנון", "מרכז העיר, מחוץ לשלושת המחוזות", "תשואה ברוטו <bdi>6.95%</bdi> לדירת חדר שינה אחד", "פתוח"],
        ["גליפדה", "פרברי הדרום", "תשואה ברוטו <bdi>3.5%</bdi>; רביעית ביוקר באטיקה", "פתוח"],
        ["ווּלה", "פרברי הדרום", "<bdi>€6,250</bdi> למ״ר (רבעון 1 של 2026)", "פתוח"],
        ["אליניקו", "פרברי הדרום", "<bdi>€5,568</bdi> למ״ר (רבעון 1 של 2026)", "פתוח"],
        ["ווליאגמני", "הריביירה", "<bdi>€7,364</bdi> למ״ר, שכירות <bdi>€22</bdi> למ״ר", "פתוח"],
        ["פיראוס", "עיר הנמל", "<bdi>€2,606</bdi> למ״ר, תשואה <bdi>5.0%</bdi>", "פתוח"]])
    ath = ath[:-1] + [
        '<h2>שכונות ואזורים: מה ידוע על כל אחד</h2>',
        '<p>אין מקור רשמי למחיר עסקאות לפי שכונה באתונה, ולכן בטבלה רק מה שפורסם: המחוז, ולכן אם מותר לרשום Airbnb חדש, ומחיר או תשואה כשיש. התשואות לפי Global Property Guide '
        'ו־Spitogatos, והמחירים לפי Spitogatos. התמונה ברורה: בשכונות היקרות והמבוקשות התשואה נמוכה, ובשכונות הזולות היא גבוהה יותר, עם יותר עבודה בניהול.</p>', HOODS,
        '<h2>המדד שנה אחרי שנה</h2>',
        '<p>ערך המדד של בנק יוון ברבעון השני של כל שנה, כש־2007 שווה 100. אתונה ירדה עד 2017, התחילה לעלות ב־2019, ומאז 2023 היא מעל הרמה של 2007.</p>',
        K.table("מדד מחירי הדירות של בנק יוון, רבעון 2 בכל שנה", ["שנה", "אתונה רבתי", "כל יוון", "סלוניקי"], yr_rows),
        '<h2>הישראלים בשוק של אתונה</h2>',
        '<p>לפי נתוני משרד ההגירה היווני, 544 משקיעים ישראלים, בלי בני המשפחה, קיבלו גולדן ויזה בתשעת החודשים הראשונים של 2025, מול 296 בתקופה המקבילה ב־2024. לפי סקר של RE/MAX יוון מ־2025, ישראלים הם מהקונים '
        'הזרים הגדולים באטיקה ובסלוניקי, והעיתונות בישראל מעריכה את ההשקעה הישראלית ביוון ביותר מחצי מיליארד אירו בשנה. גם רשתות מלונות ישראליות פעילות ביוון. המשמעות לקונה: '
        'יש בשוק הרבה מתווכים ויזמים שמדברים עברית, ולכן הבדיקה העצמאית של המחיר, הרישום והחוק חשובה עוד יותר.</p>',
        ath[-1]]
    ath_faq = [
        ("כמה עולה שכירות לדירה באתונה?", "השכירות המבוקשת במרכז העיר ובפרברי הדרום והצפון הייתה €11.8 למ״ר לחודש ברבעון 2 של 2026, כלומר כ־€826 לדירת 70 מ״ר. בווליאגמני €22 למ״ר."),
        ("מה הם מחוזות 1 עד 3 באתונה?", "שלושת המחוזות של מרכז העיר, שבהם אין רישום חדש של Airbnb: מחוז 1 (פלאקה, מונסטיראקי, סינטגמה, אומוניה, קולונקי, אקסרכיה, איליסיה, נאפולי, קוקאקי), מחוז 2 (מטס, ניאוס קוסמוס, אגיוס ארטמיוס, פנגרטי) ומחוז 3 (פטרלונה, תיסיו, גאזי, ווטניקוס, מטקסורגיו, רוף)."),
        ("האם מחירי הדירות באתונה ימשיכו לעלות?", "אף אחד לא יודע. מה שידוע: בנק יוון מדד עלייה של 9.1% ב־2024, 8.3% ב־2025 ו־5.5% בשנה שהסתיימה ברבעון 2 של 2026. הקצב מאט, והמחירים כבר מעל השיא של 2008."),
        ("כמה עולה מס רכוש על דירה באתונה?", "ENFIA לדירת 70 מ״ר ישנה כ־€267 בשנה, ולדירה חדשה של 120 מ״ר באזור יקר כ־€2,061, לפי טבלאות החוק. דירה מבוטחת מקבלת הנחה של 20%."),
        ("מה ההבדל בין מחיר מבוקש למחיר העסקה?", "המחירים בעמוד הם מחירים במודעות. מחיר הסגירה נמוך מהם לרוב, ומדד בנק יוון, שמבוסס על שמאויות של הבנקים, מתאר את המגמה ולא מחיר לדירה."),
        ("האם צריך מתווך כדי לקנות דירה באתונה?", "לא חובה. מתווך גובה לרוב 2% ועוד מע״מ 24%, ולפעמים רק המוכר משלם לו. עורך דין יווני הוא מי שבודק את הנכס ואת הרישום."),
    ]

    # ---------------- acquisition
    GVBARS = K.bars("סף הגולדן ויזה לפי אזור", [("אטיקה, סלוניקי, מיקונוס, סנטוריני ואיים גדולים", 800000, "€800,000"), ("שאר יוון", 400000, "€400,000"),
                                               ("הסבה ממסחרי או שימור, בכל מקום", 250000, "€250,000")], note="חוק 5100/2024. במסלולי 800 ו־400 אלף: נכס אחד של 120 מ״ר לפחות.")
    DOCS = K.table("המסמכים בעסקה", ["מסמך", "מי מביא", "למה"], [
        ["דרכון", "הקונה", "זיהוי מול עורך הדין, הבנק והנוטריון"],
        ["מספר מס יווני (AFM)", "הקונה, דרך משרד המס לתושבי חוץ", "בלעדיו אין עסקה"],
        ["ייפוי כוח עם אפוסטיל ותרגום ליוונית", "נוטריון בישראל", "רק אם לא חותמים בעצמכם ביוון"],
        ["תעודת מהנדס על חוקיות הבנייה, עם הצהרת הבעלים", "המוכר", "חובה בכל שטר מאז 2017"],
        ["תעודת אנרגיה", "המוכר", "חובה במכירה"],
        ["אישור העירייה שאין חוב של מס עירוני", "המוכר", "חובה לפני ההעברה"],
        ["נסח קדסטר עם מספר הנכס (KAEK)", "עורך הדין", "ההוכחה לבעלות ולשעבודים"],
        ["אישור תשלום מס ההעברה", "הקונה", "משולם לפני החתימה"]])
    loan = 180000; r = 0.042 / 12; m = loan * r / (1 - (1 + r) ** -240)
    MORT = ('<p><b>דוגמה:</b> דירה ב־<bdi>€300,000</bdi>, משכנתא של 60%, <bdi>€180,000</bdi> ל־20 שנה. בריבית של <bdi>4.20%</bdi>, ההחזר החודשי כ־<bdi>€' + n(m) + '</bdi> (<bdi>' + ILS(m) + '</bdi>). '
            'הבנק פרסם לריבית קבועה של 15 שנה <bdi>4.20%</bdi>, ואחרי התקופה הקבועה הריבית משתנה לפי היוריבור; ב־21.10.2026 היוריבור לשנה היה <bdi>3.263%</bdi>. '
            'בדוגמה של הבנק עצמו, הלוואה של <bdi>€100,000</bdi> ל־20 שנה ב־4.20% מגיעה לעלות שנתית כוללת של <bdi>4.69%</bdi>.</p>')
    acq = [
        '<h2>מה השתנה ומה עומד להשתנות</h2>', TL,
        '<h2>הסכומים של הגולדן ויזה</h2>', GVBARS,
        '<h2>המסמכים: מי מביא מה</h2>',
        '<p>רוב המסמכים מגיעים מהמוכר ומעורך הדין. מה שהקונה הישראלי מביא בעצמו הוא מעט: דרכון, מספר מס יווני, ואם לא נוסעים, ייפוי כוח עם אפוסטיל ותרגום.</p>', DOCS,
        '<h2>השווי האובייקטיבי: על מה מחושב המס</h2>',
        '<p>ליוון יש שווי רשמי לכל נכס, שמחושב לפי מחיר האזור של הכתובת, השטח, הגיל והקומה. מס ההעברה מחושב על המחיר בחוזה או על השווי הזה, הגבוה מביניהם, '
        'וגם ENFIA מחושב לפי מחיר האזור ולא לפי המחיר ששילמתם. במרכזי ערים המחיר בשוק גבוה לרוב מהשווי הרשמי, ולכן המס מחושב על המחיר. עורך הדין מוציא את מחיר '
        'האזור לכתובת לפני החתימה, וכך יודעים מראש כמה ENFIA תשלמו כל שנה.</p>',
        '<h2>קנייה עם משכנתא יוונית: דוגמה</h2>', MORT,
        '<h2>השנה הראשונה אחרי הקנייה</h2>',
        K.route([("הצהרה על הנכס (E9)", "אתם או רואה חשבון · מיד", "הנכס נרשם אצל רשות המסים היוונית, ומכאן ENFIA מחושב לפי הבעלות ב־1 בינואר."),
                 ("חשמל ומים על שמכם", "אתם · שבועות", "המס העירוני (TAP) נגבה דרך חשבון החשמל."),
                 ("ביטוח רעידות אדמה, אש והצפה", "אתם · לפני ינואר", "דירה מבוטחת מקבלת הנחה של 20% ב־ENFIA."),
                 ("השכרה", "אתם או חברת ניהול", "שכירות לטווח ארוך דרך העברה בנקאית, כדי לשמור על הניכוי של 5% במס. השכרה קצרה רק עם רישום AMA, ולא במחוזות המוקפאים."),
                 ("דוח מס ביוון", "רואה חשבון יווני · פעם בשנה", "חובה כשיש שכירות, גם למי שלא גר ביוון."),
                 ("דיווח בישראל", "רואה חשבון ישראלי", "לפי המסלול שבחרתם; דוח שנתי חובה מעל ₪2,086,000 נכסים בחו״ל.")]),
        K.sources(OFFICIAL),
    ]

    WEEKS = K.bars("כמה שבועות כל שלב, בערך", [("מספר מס יווני", 1, "עד שבוע"), ("חשבון בנק", 6, "2 עד 6"), ("בדיקת עורך דין", 4, "2 עד 4"), ("זיכרון דברים", 1, "כשבוע"),
                   ("שטר ורישום", 3, "כמה שבועות"), ("היתר אזור גבול, אם צריך", 16, "חודשים")], note="הערכות מקובלות, לא נתון רשמי. בלי היתר גבול: 6 עד 12 שבועות מהצעה עד שטר.", hi=5)
    acq = acq[:-1] + [
        '<h2>כמה זמן לוקח כל שלב</h2>', WEEKS,
        '<h2>דירה חדשה: מה בדיוק כולל השעיית המע״מ</h2>',
        '<p>ההשעיה חלה על בניינים שקיבלו היתר בנייה מ־2006 ואילך, כולל עסקאות קומבינציה (אנטיפרוכי), ועל כל הדירות שעוד לא נמכרו לפי ההיתר, ברגע שהיזם הגיש בקשה. היזם הוא שמבקש, '
        'לא הקונה. בחוזה בודקים שהיזם הגיש את הבקשה ושהמחיר כולל את מס ההעברה ולא את המע״מ. ההשעיה בחוק עד 31.12.2026, וההארכה לסוף 2027 נמצאת בהצעת התקציב.</p>',
        '<h2>הקדסטר: כמה מהמדינה כבר רשום</h2>',
        '<p>לפי הדיווחים של 2026, 99% משטח יוון כבר ממופה בקדסטר עם מספר נכס (KAEK), ויותר מ־71% מהזכויות רשומות במערכת שפועלת. היעד הוא קדסטר דיגיטלי מלא בסוף 2026. בדירה בעיר '
        'הרישום בדרך כלל ברור; בבית בכפר או באי בודקים גם את מפת היערות, כי חלק מהמגרשים סומנו בטעות כיער, ורפורמה מ־2026 מאפשרת לתקן זאת בתנאים מסוימים.</p>',
        '<h2>משכנתא יוונית: כל התנאים שפורסמו</h2>',
        K.table("התנאים של בנק יווני גדול לתושבי חוץ, אוקטובר 2026", ["תנאי", "מה פורסם"], [
            ["מימון מרבי", "<bdi>65%</bdi> מהמחיר, ולא יותר מהמחיר בחוזה"], ["הון עצמי", "לפחות <bdi>35%</bdi> ועוד העלויות"],
            ["תקופה", "עד 20 שנה לתושבי ישראל, עד 15 לאזרחים זרים אחרים"], ["גיל", "הלווה הצעיר עד גיל 75 בסוף ההלוואה"],
            ["ריבית קבועה", "<bdi>2.90%</bdi> לשלוש שנים, <bdi>3.50%</bdi> לחמש, <bdi>3.80%</bdi> לשבע, <bdi>3.90%</bdi> לעשר, <bdi>4.20%</bdi> ל־15"],
            ["אחרי התקופה הקבועה", "יוריבור לשלושה חודשים ועוד מרווח קבוע"], ["היטל לפי חוק 128/1975", "<bdi>0.12%</bdi> לדירת מגורים, <bdi>0.60%</bdi> לנכס השקעה"],
            ["דרישות", "שמאות מהנדס, ביטוח רעידות אדמה ואש, עורך דין יווני עם ייפוי כוח, בדיקה של כ־<bdi>€750</bdi>"], ["פירעון מוקדם", "בלי קנס"], ["הלוואה מינימלית", "<bdi>€10,000</bdi>"]]),
        acq[-1]]
    acq_faq = [
        ("מי משלם את מס ההעברה ביוון?", "הקונה, לפני החתימה אצל הנוטריון. השיעור היום 3.09% מהמחיר או מהשווי האובייקטיבי, הגבוה מביניהם."),
        ("מה זה שווי אובייקטיבי?", "השווי הרשמי שיוון קובעת לכל נכס, לפי מחיר האזור, השטח, הגיל והקומה. מס ההעברה מחושב עליו אם הוא גבוה מהמחיר בחוזה."),
        ("כמה עולה נוטריון ביוון?", "לפי מדרגות: 0.8% עד €120,000, 0.7% עד €380,000 ו־0.65% עד €2 מיליון, ועוד €20 ומע״מ 24%. בדירה של €250,000 כ־€" + n(buy(250000)["notary"]) + "."),
        ("מה זה KAEK?", "מספר הנכס בקדסטר היווני. עורך הדין משווה אותו לשטר ולגבולות בפועל, כי הרישום בקדסטר הוא ההוכחה לבעלות."),
        ("האם מס ה־15.45% יחול גם על חברה?", "לפי ההצעה הוא חל על אנשים פרטיים שתושבי המס שלהם מחוץ לאיחוד, ולא על חברות. ההצעה עוד לא חוק, והנוסח יכול להשתנות."),
        ("האם אפשר לקנות שתי דירות ולקבל גולדן ויזה?", "לא במסלולי 800 ו־400 אלף. החוק מ־2024 דורש נכס אחד של 120 מ״ר לפחות. רק במסלול ההסבה או השימור, 250 אלף, אין דרישת שטח."),
        ("כמה עולה ההחזר החודשי על משכנתא יוונית?", "על €180,000 ל־20 שנה בריבית של 4.20%, כ־€" + n(m) + " בחודש. הריבית הקבועה שפרסם בנק יווני גדול: 2.90% לשלוש שנים עד 4.20% ל־15 שנה."),
    ]

    # ---------------- tax
    eff = [(g, gtax(g) / g) for g in (6000, 12000, 18000, 24000, 30000, 40000)]
    EFF = K.bars("שיעור המס האפקטיבי ביוון על שכירות, לפי השכירות בשנה", [("€" + n(g), round(e * 1000) / 10, pct(e)) for g, e in eff], note="אחרי ניכוי של 5%, לפי המדרגות של 2026.")
    tax = [
        '<h2>כמה מס ביוון, לפי גובה השכירות</h2>',
        '<p>המדרגות הן על השכירות אחרי ניכוי קבוע של 5%, כך שהשיעור האפקטיבי נמוך מהמדרגה העליונה. עד <bdi>€12,000</bdi> בשנה המס כ־14%, ומעל <bdi>€30,000</bdi> הוא מתקרב ל־25%.</p>', EFF,
        '<h2>מכירה: מה קורה עם רווח ההון</h2>',
        '<p>ביוון, מס של 15% על רווח ממכירה מוקפא לאנשים פרטיים עד 31.12.2026, והצעת התקציב מאריכה את ההקפאה עד סוף 2027. מי שמוכר הרבה דירות עלול להיחשב עוסק, '
        'ואז הרווח ממוסה כהכנסה עסקית. בישראל, דירה בחו״ל היא נכס לפי פקודת מס הכנסה: אם חייבים, המס עד 25% על הרווח הריאלי, והדיווח תוך 30 יום. לפי סעיף 13 '
        'לאמנה, בנוסח האנגלי, הרווח חייב במס רק ביוון. כשהמס ביוון מוקפא, השאלה איך רשות המסים תתייחס למכירה פתוחה, ולכן לפני מכירה מקבלים חוות דעת.</p>',
        '<h2>מה מזכה בזיכוי ומה לא</h2>',
        K.table("תשלומים ביוון מול זיכוי במסלול הרגיל בישראל", ["תשלום ביוון", "זיכוי בישראל", "ניכוי כהוצאה"], [
            ["מס הכנסה על השכירות", "כן, עד גובה המס הישראלי על אותה הכנסה", "לא"],
            ["ENFIA", "לא", "כן, כהוצאה של הנכס"],
            ["מס עירוני (TAP)", "לא", "כן, כהוצאה"],
            ["מס העברה בקנייה", "לא", "לא"],
            ["דמי ניהול, דמי בניין, ביטוח", "לא", "כן"]]),
        K.sources([OFFICIAL[1], OFFICIAL[4], TREATY]),
    ]
    tax_faq = [
        ("מה זה מסלול 15% על שכירות מחו״ל?", "מסלול לפי סעיף 122א לפקודה: 15% על השכירות אחרי פחת בלבד, בלי ניכוי הוצאות, בלי קיזוז הפסדים ובלי זיכוי על המס ששולם ביוון."),
        ("האם ENFIA מזכה בזיכוי בישראל?", "לא. לפי רשות המסים, מסים עירוניים ומסי רכישה אינם מזכים בזיכוי. במסלול הרגיל אפשר לנכות אותם כהוצאה."),
        ("האם אפשר לקזז את המס ששולם ביוון?", "רק במסלול הרגיל, בטופס 1324, עד גובה המס הישראלי על אותה הכנסה. זיכוי שלא נוצל עובר עד 5 שנים."),
        ("מתי משלמים ENFIA?", "לפי הבעלות ב־1 בינואר, בתשלום אחד או ב־12 תשלומים חודשיים מסוף מרץ."),
    ]
    return {"ath": ath, "ath_faq": ath_faq, "acq": acq, "acq_faq": acq_faq, "tax": tax, "tax_faq": tax_faq}
